@ParameterizedTest
@MethodSource("parameterProvider")
public void testMatchProcessing(String id, String familyPattern, String name, String notes, String[][] targets) throws IOException {
    ILicense license = extractCategory(familyPattern, id);
    try {
        for (String[] target : targets) {
            if (processText(license, target[TEXT])) {
                data.reportOnLicense(license);
                assertEquals(1, data.licenses().count());
                assertEquals(license, data.licenses().findFirst().get());
            } else {
                fail(license + " was not matched by " + target[NAME]);
            }
            license.reset();
        }
    } finally {
        license.reset();
    }
}

@ParameterizedTest
@MethodSource("parameterProvider")
public void testEmbeddedStrings(String id, String family, String name, String notes, String[][] targets) throws IOException {
    String[] formats = { "%s", "now is not the time %s for copyright", "#%s", "##%s", "## %s", "##%s##", "## %s ##", "/*%s*/", "/* %s */" };
    ILicense license = extractCategory(family, id);
    try {
        for (String[] target : targets) {
            for (String fmt : formats) {
                boolean found = processText(license, String.format(fmt, target[TEXT]));
                license.reset();
                assertTrue(found, () -> String.format("%s %s did not match pattern '%s' for target string %s", id, name, fmt, target[NAME]));
            }
        }
    } finally {
        license.reset();
    }
}

