public void testAll() throws Exception {
    report.startReport();
    report.endReport();
    writer.closeDocument();
    String result = sw.toString();
    assertTrue(XmlUtils.isWellFormedXml(result), "Is well formed");
    XPath xPath = XPathFactory.newInstance().newXPath();
    Document doc = XmlUtils.toDom(new ByteArrayInputStream(result.getBytes()));
    // verify that all the families are there
    for (String familyName : FAMILY_IDS) {
        assertNotNull(XmlUtils.getNode(doc, xPath, String.format("/rat-config/families/family[@id='%s']", familyName)), () -> "Missing family " + familyName);
    }
    // verify that all the family ids are used in at least one license
    for (String familyName : FAMILY_IDS) {
        assertNotNull(XmlUtils.getNode(doc, xPath, String.format("/rat-config/licenses/license[@id='%s']", familyName)), () -> "Missing license " + familyName);
    }
    // verify that all matchers listed in all licenses exist in the matcher list
    for (String familyName : FAMILY_IDS) {
        List<Node> nodes = XmlUtils.getNodes(doc, xPath, String.format("/rat-config/licenses/license/*", familyName));
        nodes.stream().filter(n -> n.getNodeType() == Node.ELEMENT_NODE && !"note".equals(n.getNodeName())).forEach(n -> assertNotNull(MatcherBuilderTracker.getMatcherBuilder(n.getNodeName()), () -> String.format("Missing matcher named '%s'", n.getNodeName())));
    }
}

