@Test
public void plainReportTest() throws Exception {
    Defaults defaults = Defaults.builder().build(DefaultLog.getInstance());
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    final String elementsPath = Resources.getResourceDirectory("elements/Source.java");
    final ReportConfiguration configuration = new ReportConfiguration(DefaultLog.getInstance());
    configuration.setFrom(defaults);
    configuration.setDirectoriesToIgnore(HiddenFileFilter.HIDDEN);
    configuration.setReportable(new DirectoryWalker(configuration, new FileDocument(new File(elementsPath))));
    configuration.setOut(() -> out);
    new Reporter(configuration).output();
    out.flush();
    String document = out.toString();
    assertTrue(document.startsWith(HEADER), "'Generated at' is not present in " + document);
    TextUtils.assertPatternInTarget("^Notes: 2$", document);
    TextUtils.assertPatternInTarget("^Binaries: 2$", document);
    TextUtils.assertPatternInTarget("^Archives: 1$", document);
    TextUtils.assertPatternInTarget("^Standards: 8$", document);
    TextUtils.assertPatternInTarget("^Apache Licensed: 5$", document);
    TextUtils.assertPatternInTarget("^Generated Documents: 1$", document);
    TextUtils.assertPatternInTarget("^2 Unknown Licenses$", document);
    TextUtils.assertPatternInTarget(//
    "^Files with unapproved licenses:\\s+" + //
    "\\Qsrc/test/resources/elements/Source.java\\E\\s+" + "\\Qsrc/test/resources/elements/sub/Empty.txt\\E\\s", document);
    TextUtils.assertPatternInTarget(documentOut(true, Type.ARCHIVE, "src/test/resources/elements/dummy.jar"), document);
    TextUtils.assertPatternInTarget(documentOut(true, Type.STANDARD, "src/test/resources/elements/ILoggerFactory.java") + licenseOut("MIT", "The MIT License"), document);
    TextUtils.assertPatternInTarget(documentOut(true, Type.BINARY, "src/test/resources/elements/Image.png"), document);
    TextUtils.assertPatternInTarget(documentOut(true, Type.NOTICE, "src/test/resources/elements/LICENSE"), document);
    TextUtils.assertPatternInTarget(documentOut(true, Type.NOTICE, "src/test/resources/elements/NOTICE"), document);
    TextUtils.assertPatternInTarget(documentOut(false, Type.STANDARD, "src/test/resources/elements/Source.java") + licenseOut("?????", "Unknown license (Unapproved)"), document);
    TextUtils.assertPatternInTarget(documentOut(true, Type.STANDARD, "src/test/resources/elements/Text.txt") + licenseOut("AL", "Apache License Version 2.0"), document);
    TextUtils.assertPatternInTarget(documentOut(true, Type.STANDARD, "src/test/resources/elements/Xml.xml") + licenseOut("AL", "Apache License Version 2.0"), document);
    TextUtils.assertPatternInTarget(documentOut(true, Type.STANDARD, "src/test/resources/elements/buildr.rb") + licenseOut("AL", "Apache License Version 2.0"), document);
    TextUtils.assertPatternInTarget(documentOut(true, Type.STANDARD, "src/test/resources/elements/TextHttps.txt") + licenseOut("AL", "Apache License Version 2.0"), document);
    TextUtils.assertPatternInTarget(documentOut(true, Type.STANDARD, "src/test/resources/elements/tri.txt") + licenseOut("AL", "Apache License Version 2.0") + licenseOut("BSD-3", "BSD 3 clause") + licenseOut("BSD-3", "TMF", "The Telemanagement Forum License"), document);
    TextUtils.assertPatternInTarget(documentOut(false, Type.STANDARD, "src/test/resources/elements/sub/Empty.txt") + licenseOut("?????", "Unknown license (Unapproved)"), document);
}

